LIQUID_STARFIELD.glsl_outline:
float hash(vec2 p) { return fract(sin(p.x * 12.9898 + p.y * 78.233) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.,0.)), hash(i + vec2(1.,0.)), f.x),
               mix(hash(i + vec2(0.,1.)), hash(i + vec2(1.,1.)), f.x), f.y);
}
vec2 curl(vec2 p) { return vec2(-dFdy(noise(p)), dFdx(noise(p))); }

void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    // Flow field
    float t = iTime * (0.5 + iAudioBass * 1.0);
    vec2 flow = curl(uv * 3.0 + t) * (0.5 + iAudioMids * 0.5);

    // Star field via spatial hash
    vec2 gUv = uv * 20.0;
    vec2 cellId = floor(gUv);
    vec2 localUv = fract(gUv) - 0.5;
    float cellHash = hash12(cellId);

    float star = smoothstep(0.98, 1.0, cellHash) * (0.5 + iAudioTreble);
    float starSize = mix(0.001, 0.003, cellHash) * (1.0 + iBeatPulse);

    vec3 col = vec3(0.01, 0.01, 0.03);
    col += vec3(1.0, 0.95, 0.85) * star * (1.0 + iBeatPulse);

    // Flow trails
    float trail = noise(uv * 5.0 - flow * 0.1) * 0.1 * (0.5 + iAudioBass);
    col += vec3(0.2, 0.4, 0.6) * trail;

    float vig = 1.0 - smoothstep(0.6, 1.3, length(uv));
    col *= vig;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

PRISMATIC_SMOKE.glsl_outline:
float hash(vec2 p) { return fract(sin(p.x * 12.9898 + p.y * 78.233) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.,0.)), hash(i + vec2(1.,0.)), f.x),
               mix(hash(i + vec2(0.,1.)), hash(i + vec2(1.,1.)), f.x), f.y);
}
float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; ++i) {
        v += a * noise(p);
        p = p * 2.0 + 19.7;
        a *= 0.5;
    }
    return v;
}

void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    float t = iTime * (0.3 + iAudioBass * 0.5);
    vec2 coord = uv + vec2(sin(t * 0.2), cos(t * 0.3)) * 0.5;

    // Multi-layer smoke
    float smoke = 0.0;
    for (int i = 0; i < 3; ++i) {
        float layer = fbm(coord * (1.5 + float(i) * 0.5) + vec2(t * (0.1 + float(i) * 0.05), 0.0));
        smoke += layer * (0.3 + iAudioMids * 0.2);
    }

    // Chromatic aberration
    vec2 r = uv + vec2(iAudioTreble * 0.02, 0.0);
    vec2 b = uv - vec2(iAudioTreble * 0.02, 0.0);

    vec3 col = vec3(
        fbm(r * 1.5) * (0.5 + iAudioBass),
        fbm(uv * 1.5) * (0.3 + iAudioMids),
        fbm(b * 1.5) * (0.2 + iAudioTreble * 0.5)
    );

    col = mix(col, vec3(1.0, 0.95, 0.85), iBeatPulse * 0.5);
    col *= (0.5 + iAudioEnergy * 0.5);

    float vig = 1.0 - smoothstep(0.6, 1.4, length(uv));
    col *= vig;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

NEON_WAVEFORM_TUNNEL.glsl_outline:
float hash(vec2 p) { return fract(sin(p.x * 12.9898 + p.y * 78.233) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.,0.)), hash(i + vec2(1.,0.)), f.x),
               mix(hash(i + vec2(0.,1.)), hash(i + vec2(1.,1.)), f.x), f.y);
}

void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    float t = iTime;
    float camZ = t * (2.0 + iAudioBass * 3.0 + iBeatPulse * 2.0);

    // Waveform as tunnel cross-section
    float waveform = 0.0;
    for (int i = 0; i < 8; ++i) {
        float freq = 1.0 + float(i) * 0.5;
        waveform += sin(uv.x * freq * 10.0 + t * freq + hash12(vec2(float(i), t)) * 6.28) / float(i + 1);
    }
    waveform *= 0.15 * (0.5 + iAudioMids);

    // Perspective grid
    float depth = 0.5 / (0.1 - uv.y + 0.05);
    float gx = uv.x * depth + waveform * depth;
    float gz = depth + camZ;

    float gridX = 1.0 - smoothstep(0.0, 0.03 + iAudioMids * 0.02, abs(fract(gx) - 0.5));
    float gridZ = 1.0 - smoothstep(0.0, 0.03 + iAudioMids * 0.02, abs(fract(gz * 0.5) - 0.5));
    float line = max(gridX, gridZ);
    float fog = clamp(1.0 / (depth * 0.2), 0.0, 1.0);

    vec3 primary = vec3(0.0, 1.0, 1.0);
    vec3 secondary = vec3(1.0, 0.0, 1.0);
    vec3 gridColor = mix(primary, secondary, fract(camZ * 0.05));
    vec3 col = vec3(0.01, 0.01, 0.03);

    if (uv.y < 0.1) {
        col += gridColor * line * fog * (0.8 + iAudioBass * 0.5);
    }

    // Neon persistence trails
    float trail = sin(uv.y * 50.0 - t * 5.0) * 0.05 * iAudioTreble;
    col += vec3(0.0, 1.0, 0.5) * trail;

    float vig = 1.0 - smoothstep(0.5, 1.2, length(uv));
    col *= vig;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

ORGANIC_CELL_BLOOM.glsl_outline:
float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.13);
    p3 += dot(p3, p3.yzx + 3.33);
    return fract((p3.x + p3.y) * p3.z);
}
float hash21(vec2 p) { return hash12(p); }
vec2 hash22(vec2 p) { return vec2(hash12(p), hash12(p + 19.19)); }

void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    // Voronoi cells
    vec2 cellId = floor(uv * (5.0 + iAudioBass * 5.0));
    vec2 localUv = (fract(uv * (5.0 + iAudioBass * 5.0)) - 0.5);

    vec2 nearest = vec2(0.0);
    float nearestDist = 100.0;
    vec2 secondNearest = vec2(0.0);
    float secondDist = 100.0;

    for (int y = -1; y <= 1; ++y) {
        for (int x = -1; x <= 1; ++x) {
            vec2 neighbor = cellId + vec2(float(x), float(y));
            vec2 cellCenter = neighbor + vec2(0.5) + hash22(neighbor) - 0.5;
            vec2 diff = cellCenter - localUv;
            float d = length(diff);
            if (d < nearestDist) {
                secondDist = nearestDist;
                secondNearest = nearest;
                nearestDist = d;
                nearest = diff;
            } else if (d < secondDist) {
                secondDist = d;
                secondNearest = diff;
            }
        }
    }

    // Cell edges
    float edge = smoothstep(0.0, 0.01, nearestDist) * (0.5 + iAudioBass * 0.5);

    // Cell growth
    float growth = 0.3 + iAudioMids * 0.5 + sin(iTime * 0.5) * 0.1;
    float cellSize = growth * (1.0 + iAudioEnergy * 0.3);

    // Bloom
    float bloom = exp(-nearestDist * 20.0) * (0.5 + iAudioEnergy) * (1.0 + iBeatPulse);

    vec3 primary = vec3(0.1, 0.8, 0.9);
    vec3 secondary = vec3(0.9, 0.2, 0.9);
    vec3 col = mix(primary, secondary, iAudioBass) * edge * (1.0 + iBeatPulse);
    col += vec3(1.0, 0.95, 0.8) * bloom;

    // Beat flash on edges
    col += vec3(1.0, 0.95, 0.85) * iBeatPulse * 0.3;

    float vig = 1.0 - smoothstep(0.7, 1.3, length(uv));
    col *= vig;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

FRACTAL_PULSE_MANDALA.glsl_outline:
float2 complexSqr(float2 z) { return float2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y); }

void main() {
    float aspect = iAspect > 0.0 ? iAspect : 1.0;
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= aspect;

    // Beat-synced zoom
    float zoom = 0.8 + iAudioEnergy * 0.6 + iBeatPulse * 0.5;
    float iterCap = 24.0 + iAudioBass * 28.0;

    // Mids-driven domain drift
    float drift = iTime * (0.05 + iAudioMids * 0.15);
    float2 center = float2(-0.5 + sin(drift) * 0.2, 0.0 + cos(drift * 0.7) * 0.2);

    float2 z = uv * zoom + center;
    float2 c = z;
    float dist2 = 0.0, n = 0.0;

    for (int i = 0; i < 52; ++i) {
        if (float(i) > iterCap) break;
        z = complexSqr(z) + c;
        dist2 = dot(z, z);
        if (dist2 > 4.0) break;
        n += 1.0;
    }

    float mu = n + log2(0.5 * log2(dist2)) - iterCap;
    float tNorm = clamp(n / iterCap, 0.0, 1.0);

    // Color: bass → depth, mids → hue shift, treble → boundary sparkle
    vec3 col = mix(vec3(0.10, 0.02, 0.22), vec3(0.05, 0.55, 0.55), tNorm);
    col = mix(col, vec3(0.9, 0.95, 1.0), tNorm * tNorm * iAudioTreble);

    if (dist2 <= 4.0) col *= 0.15;

    float boundary = smoothstep(0.94, 1.0, tNorm) * (1.0 - step(4.0, dist2 + 0.001));
    col += vec3(0.8, 0.9, 1.0) * boundary * iAudioTreble * 1.2;

    // Beat pulse
    col += vec3(1.0, 0.95, 1.0) * iBeatPulse * 0.3;

    col *= iIntensity;
    float vig = 1.0 - smoothstep(0.7, 1.5, length(uv));
    col *= vig;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

MINIMAL_BASS_ORBIT.glsl_outline:
float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.13);
    p3 += dot(p3, p3.yzx + 3.33);
    return fract((p3.x + p3.y) * p3.z);
}

void main() {
    float aspect = iAspect > 0.0 ? iAspect : 1.0;
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= aspect;

    // Bass-only: orbit count, radius, speed
    int orbitCount = int(3.0 + iAudioBass * 5.0);
    float baseRadius = 0.15 + iAudioBass * 0.3;
    float speed = 0.5 + iAudioBass * 1.0;

    vec3 col = vec3(0.02, 0.02, 0.05);
    vec3 primary = vec3(0.10, 0.85, 0.95);
    vec3 secondary = vec3(0.85, 0.15, 0.85);

    for (int i = 0; i < 8; ++i) {
        if (float(i) >= float(orbitCount)) break;

        float phase = iTime * speed + float(i) * 6.28 / float(orbitCount);
        float radius = baseRadius * (1.0 + float(i) * 0.2);

        float2 orbitPos = float2(cos(phase) * radius, sin(phase) * radius);
        float2 diff = uv - orbitPos;
        float dist = length(diff);

        float ring = smoothstep(0.01, 0.002, abs(dist - 0.02));
        float glow = exp(-dist * 15.0);

        vec3 orbitColor = mix(primary, secondary, float(i) / float(orbitCount));
        col += orbitColor * ring * (1.0 + iAudioBass);
        col += orbitColor * glow * (0.5 + iAudioBass * 0.5);
    }

    // Center core
    float coreDist = length(uv);
    float coreRing = smoothstep(0.005, 0.001, abs(coreDist - 0.03)) * (1.0 + iAudioBass * 2.0);
    col += vec3(1.0, 0.95, 0.85) * coreRing * (1.0 + iBeatPulse);

    col *= 1.0 - smoothstep(0.6, 1.2, length(uv));
    col *= iIntensity;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}
